"""Generated by Step 10 of the corresponding assignment notebook."""
from pathlib import Path
import math
import pickle
import pandas as pd
import streamlit as st

TASK = 'Titanic'
BASE = Path(__file__).resolve().parent
st.set_page_config(page_title=TASK.replace('_', ' ') + ' Predictor', page_icon='📊', layout='centered')

@st.cache_resource
def load_bundle(model_file):
    with Path(model_file).open('rb') as stream:
        return pickle.load(stream)

def predict(values, bundle):
    if set(values) != set(bundle['features']):
        raise ValueError('Provide exactly the four required inputs.')
    row = pd.DataFrame([values], columns=bundle['features'])
    if TASK == 'Heart_Disease':
        for field, low, high in [('age', 1, 120), ('thalach', 30, 250)]:
            value = float(row.at[0, field])
            if not math.isfinite(value) or not low <= value <= high or not value.is_integer():
                raise ValueError(f'{field} must be a whole number from {low} to {high}.')
            row[field] = value
    for field, encoder in bundle['encoders'].items():
        if row.at[0, field] not in encoder.classes_:
            raise ValueError(f'Invalid category for {field}.')
        row[field] = encoder.transform(row[field])
    label = int(bundle['model'].predict(row)[0])
    return label, bundle['labels'][label]

st.title('Titanic Survival Predictor' if TASK == 'Titanic' else 'Heart Disease Predictor')
st.caption('AIC354 · Assignment 2 · Muhammad Bilal Nawaz · SP24-BSE-070')
bundle = load_bundle(str(BASE / 'models/model_bundle.pkl'))
if TASK == 'Heart_Disease':
    st.info('Educational demonstration using historical UCI data. This is not a medical diagnosis.')
    st.write('Enter four attributes to run the trained classifier.')
else:
    st.write('Explore a classifier trained on the instructor’s 100-passenger teaching sample.')

with st.form('prediction_form'):
    if TASK == 'Titanic':
        values = {
            'PClass': st.selectbox('Passenger class', ['First', 'Second', 'Third']),
            'Gender': st.selectbox('Gender', ['Male', 'Female']),
            'Sibling': st.selectbox('Siblings / spouses aboard', ['Zero', 'One', 'Two', 'Three']),
            'Embarked': st.selectbox('Embarkation port', ['Southampton', 'Cherbourg', 'Queenstown'])
        }
    else:
        pain = {1: 'Typical angina', 2: 'Atypical angina', 3: 'Non-anginal pain', 4: 'Asymptomatic'}
        values = {
            'age': st.number_input('Age (years)', min_value=1, max_value=120, value=54, step=1),
            'cp': st.selectbox('Chest-pain type', [1, 2, 3, 4], format_func=lambda x: pain[x]),
            'thalach': st.number_input('Maximum heart rate achieved (beats/min)', min_value=30, max_value=250, value=150, step=1),
            'exang': st.selectbox('Exercise-induced angina', [0, 1], format_func=lambda x: 'Yes' if x else 'No')
        }
    submitted = st.form_submit_button('Predict', type='primary')
if submitted:
    try:
        label, wording = predict(values, bundle)
        st.success('Model prediction: ' + wording)
        st.caption('Predicted class: ' + str(label) + '. This is a class label, not a probability.')
        if TASK == 'Heart_Disease' and any(not bounds[0] <= values[field] <= bounds[1] for field, bounds in bundle['observed_ranges'].items()):
            st.warning('An input is outside the training data range; this prediction may be unreliable.')
    except (ValueError, TypeError) as error:
        st.error(str(error))
with st.expander('Model and evaluation'):
    st.write('Inputs:', ', '.join(bundle['features']))
    st.write('Held-out test accuracy:', f"{bundle['metrics']['accuracy']:.1%}")
    st.write('Test rows:', bundle['metrics']['test_rows'])
    st.write('Small historical datasets limit generalization. No live feedback has been used to retrain this model.')
    st.markdown('[Data and notebook source](' + bundle['source_url'] + ')')
st.caption('Inputs are used for this prediction only; the app does not write patient or passenger records.')
